package com.aistock.notification.alert;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import java.time.*;import java.util.*;import java.math.BigDecimal;import java.security.MessageDigest;import java.nio.charset.StandardCharsets;
public final class AlertEvidenceClient {
 private final AlertRemoteHttp http;private final Clock clock;private final int updateHour;
 public AlertEvidenceClient(AlertRemoteHttp http,Clock clock){this(http,clock,20);}
 public AlertEvidenceClient(AlertRemoteHttp http,Clock clock,int updateHour){if(updateHour<0||updateHour>23)throw new IllegalArgumentException("Invalid update hour");this.http=http;this.clock=clock;this.updateHour=updateHour;}
 public record Day(LocalDate date,boolean open){}
 public record Evidence(UUID id,String instrumentId,String provider,String definition,LocalDate tradeDate,LocalDate previousTradeDate,UUID rawVersionId,String rawContentHash,UUID calendarVersionId,String calendarHash,List<Day> calendarDays,String priceState,String rawClose,String changeState,String previousBackwardClose,String currentBackwardClose,String sourcePayloadHash,Instant capturedAt,String contentHash){}
 public record Reference(UUID evidenceId,String instrumentId,UUID rawVersionId){}
 public Reference reference(UUID id){if(id==null)throw AlertRemoteHttp.invalid();var n=http.get("stock-market-service","/internal/v1/market/alert-evidence-references/"+id);if(n.size()!=3||!n.path("evidenceId").isTextual()||!n.path("instrumentId").isTextual()||!n.path("rawVersionId").isTextual()||!AlertRemoteHttp.uuid(n.path("evidenceId").asText())||!AlertRemoteHttp.uuid(n.path("rawVersionId").asText())||!n.path("instrumentId").asText().matches("(SH|SZ)[0-9]{6}")||!id.toString().equals(n.path("evidenceId").asText()))throw AlertRemoteHttp.invalid();return new Reference(id,n.path("instrumentId").asText(),UUID.fromString(n.path("rawVersionId").asText()));}
 public Evidence read(UUID id){if(id==null)throw AlertRemoteHttp.invalid();var n=http.get("stock-market-service","/internal/v1/market/alert-evidence/versions/"+id);try{
  for(String field:List.of("id","instrumentId","provider","definition","tradeDate","rawVersionId","rawContentHash","calendarHash","priceState","changeState","capturedAt","contentHash"))if(!n.path(field).isTextual())throw AlertRemoteHttp.invalid();
  for(String field:List.of("previousTradeDate","calendarVersionId","rawClose","previousBackwardClose","currentBackwardClose","sourcePayloadHash"))if(!n.has(field)||!n.get(field).isNull()&&!n.get(field).isTextual())throw AlertRemoteHttp.invalid();
  for(String field:List.of("id","rawVersionId","calendarVersionId"))if(n.hasNonNull(field)&&!AlertRemoteHttp.uuid(n.get(field).textValue()))throw AlertRemoteHttp.invalid();
  if(!n.path("calendarDays").isArray()||n.path("calendarDays").size()>400)throw AlertRemoteHttp.invalid();for(var day:n.get("calendarDays"))if(!day.isObject()||day.size()!=2||!day.path("date").isTextual()||!day.path("open").isBoolean())throw AlertRemoteHttp.invalid();
  var e=http.mapper.treeToValue(n,Evidence.class);if(!id.equals(e.id())||e.instrumentId()==null||!e.instrumentId().matches("(SH|SZ)[0-9]{6}")||!"baostock".equals(e.provider())||!"alert-daily-evidence-v1".equals(e.definition())||e.capturedAt().isAfter(clock.instant().plusSeconds(5))||e.tradeDate().isAfter(clock.instant().atZone(ZoneId.of("Asia/Shanghai")).toLocalDate()))throw AlertRemoteHttp.invalid();
  for(String hash:List.of(e.rawContentHash(),e.calendarHash(),e.contentHash()))if(!hash.matches("[a-f0-9]{64}"))throw AlertRemoteHttp.invalid();
  if(!Set.of("VERIFIED","MISSING","SUSPENDED").contains(e.priceState())||!Set.of("VERIFIED","MISSING_CURRENT_RAW","MISSING_PREVIOUS_RAW","MISSING_PREVIOUS_CALENDAR","SUSPENDED","SOURCE_INVALID","SOURCE_UNAVAILABLE").contains(e.changeState()))throw AlertRemoteHttp.invalid();
  if("VERIFIED".equals(e.priceState()))decimal(e.rawClose());else if(e.rawClose()!=null)throw AlertRemoteHttp.invalid();
  var days=new TreeMap<LocalDate,Boolean>();var calendar=new StringBuilder();LocalDate prior=null;for(var day:e.calendarDays()){if(prior!=null&&!day.date().equals(prior.plusDays(1)))throw AlertRemoteHttp.invalid();days.put(day.date(),day.open());calendar.append(day.date()).append(':').append(day.open()?'1':'0').append('\n');prior=day.date();}
  if(!Boolean.TRUE.equals(days.get(e.tradeDate()))||!hash(calendar.toString().getBytes(StandardCharsets.UTF_8)).equals(e.calendarHash()))throw AlertRemoteHttp.invalid();
  if(e.previousTradeDate()!=null){var previous=days.headMap(e.tradeDate(),false).descendingMap().entrySet().stream().filter(Map.Entry::getValue).map(Map.Entry::getKey).findFirst().orElse(null);if(!e.previousTradeDate().equals(previous))throw AlertRemoteHttp.invalid();}
  if("VERIFIED".equals(e.changeState())){decimal(e.previousBackwardClose());decimal(e.currentBackwardClose());if(!"VERIFIED".equals(e.priceState())||e.previousTradeDate()==null||e.sourcePayloadHash()==null||!e.sourcePayloadHash().matches("[a-f0-9]{64}"))throw AlertRemoteHttp.invalid();}else if(e.previousBackwardClose()!=null||e.currentBackwardClose()!=null||e.sourcePayloadHash()!=null)throw AlertRemoteHttp.invalid();
  ObjectNode canonical=http.mapper.valueToTree(e);canonical.remove(List.of("id","contentHash"));if(!hash(http.mapper.writeValueAsBytes(canonical)).equals(e.contentHash()))throw AlertRemoteHttp.invalid();return e;
 }catch(com.aistock.common.BusinessException error){throw error;}catch(Exception error){throw AlertRemoteHttp.invalid();}}
 public AlertRecords.Boundary boundary(String stock){if(stock==null||!stock.matches("(SH|SZ)[0-9]{6}"))throw AlertRemoteHttp.invalid();var n=http.get("stock-market-service","/internal/v1/market/alert-boundary/"+stock);try{for(String field:List.of("instrumentId","provider","rawVersionId","latestPublishedTradeDate","expectedCompletedTradeDate","effectiveAfterTradeDate","calendarHash","asOf","definition"))if(!n.path(field).isTextual())throw AlertRemoteHttp.invalid();if(!AlertRemoteHttp.uuid(n.get("rawVersionId").textValue()))throw AlertRemoteHttp.invalid();var local=clock.instant().atZone(ZoneId.of("Asia/Shanghai"));var cutoff=local.toLocalDate().minusDays(local.getHour()<updateHour?1:0);var b=http.mapper.treeToValue(n,AlertRecords.Boundary.class);if(!stock.equals(b.instrumentId())||!"baostock".equals(b.provider())||!"alert-boundary-v1".equals(b.definition())||b.rawVersionId()==null||b.asOf()==null||b.asOf().isBefore(clock.instant().minusSeconds(5))||b.asOf().isAfter(clock.instant().plusSeconds(5))||b.latestPublishedTradeDate()==null||b.expectedCompletedTradeDate()==null||b.effectiveAfterTradeDate()==null||!b.effectiveAfterTradeDate().equals(b.latestPublishedTradeDate().isAfter(b.expectedCompletedTradeDate())?b.latestPublishedTradeDate():b.expectedCompletedTradeDate())||b.latestPublishedTradeDate().isAfter(cutoff)||b.expectedCompletedTradeDate().isAfter(cutoff)||b.calendarHash()==null||!b.calendarHash().matches("[a-f0-9]{64}"))throw AlertRemoteHttp.invalid();return b;}catch(com.aistock.common.BusinessException error){throw error;}catch(Exception error){throw AlertRemoteHttp.invalid();}}
 private static void decimal(String value){if(value==null||!value.matches("[0-9]{1,16}(\\.[0-9]{1,12})?"))throw AlertRemoteHttp.invalid();var n=new BigDecimal(value);if(n.signum()<=0||n.precision()>28)throw AlertRemoteHttp.invalid();}
 private static String hash(byte[] value)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value));}
}
